#generated by AI

import os
import matplotlib.pyplot as plt
import pandas as pd
import seaborn as sns

sns.set_theme(style="whitegrid")
plt.rcParams.update({
    'font.size': 12,
    'font.family': 'sans-serif',
    'axes.labelsize': 14,
    'axes.titlesize': 16,
    'xtick.labelsize': 12,
    'ytick.labelsize': 12,
    'figure.titlesize': 18,
    'pdf.fonttype': 42,
    'ps.fonttype': 42
})

OUTPUT_DIR = "output_plots"
os.makedirs(OUTPUT_DIR, exist_ok=True)

csv_path = 'nids_gpu_in_memory_benchmark.csv'
if not os.path.exists(csv_path) and os.path.exists(f'../{csv_path}'):
    csv_path = f'../{csv_path}'

df = pd.read_csv(csv_path)

df_stats = df.groupby('rx_queues').agg({
    'throughput_gbps': ['mean', 'std']
}).reset_index()

df_stats.columns = ['rx_queues', 'throughput_mean', 'throughput_std']
df_stats = df_stats.fillna(0)

queues = df_stats['rx_queues'].tolist()
means = df_stats['throughput_mean'].tolist()
stds = df_stats['throughput_std'].tolist()

plt.figure(figsize=(8, 6))

bars = plt.bar([str(q) for q in queues], means, yerr=stds, capsize=5, color='#1f77b4', alpha=0.85, width=0.4, zorder=3)

plt.xlabel('Number of RX Queues')
plt.ylabel('Throughput (Gbps)')
plt.title('Multi-Queue RX Scaling Performance', pad=15)
plt.grid(True, linestyle='--', alpha=0.5, zorder=0)

min_val = min(means) - max(stds) if means else 0
max_val = max(means) + max(stds) if means else 10
plt.ylim(max(0, min_val * 0.9), max_val * 1.15)

for bar in bars:
    yval = bar.get_height()
    plt.text(bar.get_x() + bar.get_width()/2, yval + (max_val * 0.02), 
             f'{yval:.2f} Gbps', ha='center', fontweight='bold', fontsize=11)

plt.tight_layout()
output_path = os.path.join(OUTPUT_DIR, 'chart_multi_queues_scaling.pdf')
plt.savefig(output_path, format='pdf', bbox_inches='tight')
plt.close()

print(f"Generated: {output_path}")